  parameters: {
    docs: {
      description: { story: "Package-manager commands use the same block and copy the active tab." },
      source: { code: CommandsSource },
    },
  },
  render: CommandsExample,
};

export const Files: Story = {
  parameters: {
    docs: {
      description: { story: "Switch files with line numbers and a disabled tab.

Each tab includes the icon for its own source language, including disabled tabs." },
      source: { code: FilesSource },
    },
  },
  render: FilesExample,
};

export const Controlled: Story = {
  parameters: {
    docs: {
      description: { story: "Synchronize package-manager selection across multiple blocks." },
      source: { code: ControlledSource },
    },
  },
  render: ControlledExample,
};

export const Composition: Story = {
  parameters: {
    docs: {
      description: { story: "Compose a custom header and the existing copy button labels.

Place `CodeBlockIcon` before the title to use the active source’s language icon." },
      source: { code: CompositionSource },
    },
  },
  render: CompositionExample,
};

export const Overflow: Story = {
  parameters: {
    docs: {
      description: { story: "Compare horizontal scrolling, wrapping, and bounded height." },
      source: { code: OverflowSource },
    },
  },
  render: OverflowExample,
};

export const LineNumbers: Story = {
  parameters: {
    docs: {
      description: { story: "Set `startLine` to number an excerpt from the middle of a file. The gutter grows to fit the widest number, so every line stays aligned, and wrapped lines continue in the code column rather than under the number." },
      source: { code: LineNumbersSource },
    },
  },
  render: LineNumbersExample,
};

export const HighlightedLines: Story = {
  parameters: {
    docs: {
      description: { story: "Pass the displayed numbers of the lines to call out to `highlightLines`. Each highlighted line gets a tint across the block and a marker on its leading edge." },
      source: { code: HighlightedLinesSource },
    },
  },
